module max_density_subsequence (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] k,\n    input wire [3:0] L,\n    input wire [15:0] str,\n    output reg [4:0] start_index,\n    output reg [4:0] length,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE  = 3'd0;\n    localparam [2:0] INIT  = 3'd1;\n    localparam [2:0] LOOP_I = 3'd2;\n    localparam [2:0] LOOP_J = 3'd3;\n    localparam [2:0] UPDATE = 3'd4;\n    localparam [2:0] FINISH = 3'd5;\n    \n    reg [2:0] state, next_state;\n    reg [3:0] i, next_i;\n    reg [3:0] j, next_j;\n    reg [4:0] count, next_count;\n    reg [4:0] best_start, next_best_start;\n    reg [4:0] best_len, next_best_len;\n    reg [4:0] best_ones, next_best_ones;\n    reg next_done;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            i <= 4'd0;\n            j <= 4'd0;\n            count <= 5'd0;\n            best_start <= 5'd0;\n            best_len <= 5'd0;\n            best_ones <= 5'd0;\n            done <= 1'b0;\n            start_index <= 5'd0;\n            length <= 5'd0;\n        end else begin\n            state <= next_state;\n            i <= next_i;\n            j <= next_j;\n            count <= next_count;\n            best_start <= next_best_start;\n            best_len <= next_best_len;\n            best_ones <= next_best_ones;\n            done <= next_done;\n            start_index <= next_best_start + 5'd1;\n            length <= next_best_len;\n        end\n    end\n    \n    always @(*) begin\n        next_state = state;\n        next_i = i;\n        next_j = j;\n        next_count = count;\n        next_best_start = best_start;\n        next_best_len = best_len;\n        next_best_ones = best_ones;\n        next_done = 1'b0;\n        \n        case (state)\n            IDLE: begin\n                if (start) begin\n                    next_state = INIT;\n                end\n            end\n            \n            INIT: begin\n                next_i = 4'd0;\n                next_j = 4'd0;\n                next_count = 5'd0;\n                next_best_start = 5'd0;\n                next_best_len = 5'd0;\n                next_best_ones = 5'd0;\n                next_state = LOOP_I;\n            end\n            \n            LOOP_I: begin\n                next_j = next_i;\n                next_count = 5'd0;\n                if (i < L) begin\n                    next_state = LOOP_J;\n                end else begin\n                    next_state = FINISH;\n                end\n            end\n            \n            LOOP_J: begin\n                next_count = count + {{4{1'b0}}, str[j]};  // Extend 1-bit to 5-bit\n                if ((j - i + 4'd1) >= k) begin\n                    next_state = UPDATE;\n                end else begin\n                    next_j = j + 4'd1;\n                    if (next_j >= L) begin\n                        next_i = i + 4'd1;\n                        next_state = LOOP_I;\n                    end\n                end\n            end\n            \n            UPDATE: begin\n                if ((best_len == 5'd0) || (count * best_len > best_ones * (j - i + 1))) begin\n                    next_best_start = i;\n                    next_best_len = j - i + 5'd1;\n                    next_best_ones = count;\n                end\n                next_j = j + 4'd1;\n                if (next_j >= L) begin\n                    next_i = i + 4'd1;\n                    next_state = LOOP_I;\n                end else begin\n                    next_state = LOOP_J;\n                end\n            end\n            \n            FINISH: begin\n                next_done = 1'b1;\n                next_state = IDLE;\n            end\n            \n            default: next_state = IDLE;\n        endcase\n    end\n    \nendmodule